// Constrói o payload de contexto que vai ao AI Agent
const cliente   = $('Upsert Cliente + Get Estado').first().json;
const historico = $('Get Histórico (12 últimas)').all().map(i => ({ sender: i.json.sender, msg: i.json.mensagem })).reverse();
const msg       = $('Normalize Input (Baileys Bridge)').first().json.mensagem;
const agoraDate = new Date();
const diaSemana = ['domingo','segunda','terça','quarta','quinta','sexta','sábado'][agoraDate.getDay()];
const data = agoraDate.toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const hora = agoraDate.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false });

return [{
  json: {
    contexto: {
      estado_atual:  cliente.estado_atual,
      agora: {
        data,
        hora,
        dia_semana: diaSemana
      },
      cliente: {
        nome:     cliente.nome,
        telefone: cliente.telefone,
        endereco: cliente.endereco
      },
      carrinho:        cliente.contexto?.carrinho        || [],
      dados_parciais:  cliente.contexto?.dados_parciais  || {},
      historico,
      mensagem_atual:  msg
    }
  }
}];

