// Normaliza a saída da IA para o formato real esperado pelo workflow.
let raw = $json.output ?? $json.text ?? $json.response ?? '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
let parsed;
try {
  const cleaned = String(raw).replace(/```json|```/g,'').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

const cliente = $('Upsert Cliente + Get Estado').first().json;
const dados = parsed.dados_coletados || parsed.dados_parciais || parsed.dados || {};
const pedido = parsed.pedido || {};

let itens = Array.isArray(parsed.carrinho)
  ? parsed.carrinho
  : (Array.isArray(pedido.itens) ? pedido.itens.map(i => ({
      item: i.item || i.nome || i.produto || '',
      qtd: Number(i.qtd || i.quantidade || 0),
      preco_unit: Number(i.preco_unit || i.preco || 0)
    })) : []);

if (!itens.length && (pedido.item || dados.item)) {
  itens = [{
    item: pedido.item || dados.item || '',
    qtd: Number(pedido.quantidade || dados.quantidade || 0),
    preco_unit: Number(pedido.preco_unit || dados.preco_unit || 0)
  }];
}

const acaoBruta = String(parsed.acao || parsed.action || '').toUpperCase().trim();
const temNome = !!(dados.nome || pedido.nome || pedido.nome_cliente || cliente.nome);
const temItens = Array.isArray(itens) && itens.some(i => (i?.item || '').trim() && Number(i?.qtd || 0) > 0);
const temData = !!(dados.data || pedido.data || pedido.retirada?.data);
const temHorario = !!(dados.horario || pedido.horario || pedido.retirada?.horario);
const pedidoCompletoInferido = temNome && temItens && temData && temHorario;
let acao = 'NENHUMA';
if (acaoBruta === 'CONFIRMAR_PEDIDO' || acaoBruta === 'CRIAR_PEDIDO') acao = 'CRIAR_PEDIDO';
else if (acaoBruta === 'ESCALAR_HUMANO' || acaoBruta === 'HUMANO') acao = 'ESCALAR_HUMANO';
else if (acaoBruta === 'CANCELAR' || acaoBruta === 'CANCELADO') acao = 'CANCELAR';
else if (pedidoCompletoInferido) acao = 'CRIAR_PEDIDO';

const estadoIA = String(parsed.novo_estado || parsed.estado_atual || '').toUpperCase().trim();
const estadosPermitidos = new Set(['INICIO','COLETANDO_PEDIDO','CONFIRMANDO_PEDIDO','AGUARDANDO_ENDERECO','AGUARDANDO_PAGAMENTO','PEDIDO_CONFIRMADO','EM_PREPARO','PRONTO','FINALIZADO','HUMANO']);
const mapaEstados = {
  AGUARDANDO_ITEM: 'COLETANDO_PEDIDO',
  AGUARDANDO_ITENS: 'COLETANDO_PEDIDO',
  AGUARDANDO_QTD: 'COLETANDO_PEDIDO',
  AGUARDANDO_QUANTIDADE: 'COLETANDO_PEDIDO',
  COLETANDO_ITENS: 'COLETANDO_PEDIDO',
  AGUARDANDO_NOME: 'COLETANDO_PEDIDO',
  AGUARDANDO_DATA: 'COLETANDO_PEDIDO',
  AGUARDANDO_HORARIO: 'COLETANDO_PEDIDO',
  AGUARDANDO_ENTREGA: 'AGUARDANDO_ENDERECO',
  AGUARDANDO_ENDEREÇO: 'AGUARDANDO_ENDERECO',
  AGUARDANDO_PAGTO: 'AGUARDANDO_PAGAMENTO',
  PAGAMENTO_PENDENTE: 'AGUARDANDO_PAGAMENTO',
  PEDIDO_FECHADO: 'PEDIDO_CONFIRMADO',
  CONCLUIDO: 'FINALIZADO',
  CONCLUÍDO: 'FINALIZADO',
  PRONTO_PARA_CONFIRMACAO: 'CONFIRMANDO_PEDIDO',
  DADOS_COMPLETOS: 'CONFIRMANDO_PEDIDO',
  PEDIDO_COMPLETO: 'CONFIRMANDO_PEDIDO'
};
let novoEstado = mapaEstados[estadoIA] || estadoIA;
if (!estadosPermitidos.has(novoEstado)) {
  if (acao === 'CRIAR_PEDIDO') novoEstado = 'CONFIRMANDO_PEDIDO';
  else if (acao === 'ESCALAR_HUMANO') novoEstado = 'HUMANO';
  else if (dados.item || itens.length) novoEstado = 'COLETANDO_PEDIDO';
  else novoEstado = cliente.estado_atual || 'INICIO';
}

const resposta = parsed.resposta_cliente || parsed.mensagem || parsed.resposta || 'Desculpa, tive um errinho aqui. Pode repetir? 🙏';
const formaPagamento = dados.forma_pagamento || pedido.forma_pagamento || 'dinheiro';
const tipoEntrega = dados.tipo_entrega || dados.tipo_atendimento || pedido.tipo_entrega || pedido.tipo_atendimento || (pedido.retirada ? 'retirada' : 'entrega');

const dados_coletados = {
  nome: dados.nome || pedido.nome || pedido.nome_cliente || cliente.nome || 'Cliente',
  item: dados.item || pedido.item || pedido.produto || (itens[0] && itens[0].item) || '',
  quantidade: Number(dados.quantidade || pedido.quantidade || (itens[0] && itens[0].qtd) || 0),
  data: dados.data || pedido.data || '',
  horario: dados.horario || pedido.horario || '',
  tipo_entrega: tipoEntrega,
  endereco: dados.endereco || pedido.endereco || (tipoEntrega === 'retirada' ? '' : 'endereco-pendente'),
  forma_pagamento: formaPagamento,
  observacao: dados.observacao || pedido.observacao || ''
};

return [{ json: {
  resposta_cliente: resposta,
  novo_estado: novoEstado,
  carrinho: itens,
  dados_coletados,
  acao,
  intencao: parsed.intencao || parsed.intent || acao.toLowerCase(),
  pedido,
  estado_ia_original: estadoIA || null
} }];
